def compute_model_placement(gpu_num, models):
    """
    Multi-start greedy placement: try several model orderings (pressure desc,
    size desc, pressure/size desc, plus random shuffles), place each model on
    the GPU minimizing the resulting KVPR, then refine each candidate with
    best-improvement moves/swaps. Return the best placement found.
    """
    import random

    def greedy(order):
        placement = {g: [] for g in range(gpu_num)}
        free = [GPU_MEM_SIZE] * gpu_num
        press = [0.0] * gpu_num
        for m in order:
            best_g, best_v = None, float('inf')
            for g in range(gpu_num):
                rem = free[g] - m.model_size
                if rem > 0:
                    v = (press[g] + m.req_rate / m.slo) / rem
                    if v < best_v:
                        best_v, best_g = v, g
            if best_g is None:
                return None
            placement[best_g].append(m)
            press[best_g] += m.req_rate / m.slo
            free[best_g] -= m.model_size
        return placement, press, free

    def score(press, free):
        best = 0.0
        for g in range(gpu_num):
            if free[g] > 0:
                best = max(best, press[g] / free[g])
            elif press[g] > 0:
                return float('inf')
        return best

    orders = [
        sorted(models, key=lambda m: m.req_rate / m.slo, reverse=True),
        sorted(models, key=lambda m: m.model_size, reverse=True),
        sorted(models, key=lambda m: (m.req_rate / m.slo) / max(m.model_size, 1e-9), reverse=True),
    ]
    rng = random.Random(0)
    for _ in range(5):
        o = models[:]
        rng.shuffle(o)
        orders.append(o)

    best_place, best_score = None, float('inf')
    for order in orders:
        res = greedy(order)
        if res is None:
            continue
        placement, press, free = refine(placement, press, free) if False else res
        s = score(press, free)
        if s < best_score:
            best_score, best_place = s, placement

    if best_place is None:
        raise ValueError("Cannot fit all models into GPUs")

    return best_place

def _unused_refine(placement, press, free, gpu_num):
    def kvpr(p, f):
        return p / f if f > 0 else float('inf')

    return placement

