def compute_model_placement(gpu_num, models):
    """
    Multi-start greedy placement: try several model orderings (pressure desc,
    size desc, pressure/size desc, plus a few random shuffles), place each
    model on the GPU minimizing the resulting KVPR, then refine each candidate
    with best-improvement moves/swaps. Return the best placement found.
    """
    import random

    def greedy(order):
        placement = {g: [] for g in range(gpu_num)}
        free = [GPU_MEM_SIZE] * gpu_num
        press = [0.0] * gpu_num
        for m in order:
            best_g, best_v = None, float('inf')
            for g in range(gpu_num):
                rem = free[g] - m.model_size
                if rem > 0:
                    v = (press[g] + m.req_rate / m.slo) / rem
                    if v < best_v:
                        best_v, best_g = v, g
            if best_g is None:
                return None
            placement[best_g].append(m)
            press[best_g] += m.req_rate / m.slo
            free[best_g] -= m.model_size
        return placement, press, free

    def refine(placement, press, free):
        def kvpr(p, f):
            return p / f if f > 0 else float('inf')
        improved = True
        while improved:
            improved = False
            cur = max(kvpr(press[g], free[g]) for g in range(gpu_num))
            best = None
            for src in range(gpu_num):
                for m in placement[src]:
                    pm = m.req_rate / m.slo
                    for dst in range(gpu_num):
                        if dst == src or m.model_size > free[dst]:
                            continue
                        others = max((kvpr(press[g], free[g])
                                      for g in range(gpu_num) if g != src and g != dst),
                                     default=0.0)
                        cand = max(kvpr(press[src] - pm, free[src] + m.model_size),
                                   kvpr(press[dst] + pm, free[dst] - m.model_size),
                                   others)
                        if cand < cur and (best is None or cand < best[0]):
                            best = (cand, 'move', src, dst, m)
            for src in range(gpu_num):
                for dst in range(src + 1, gpu_num):
                    for m1 in placement[src]:
                        for m2 in placement[dst]:
                            d = m1.model_size - m2.model_size
                            if d > free[dst] or -d > free[src]:
                                continue
                            p1 = m1.req_rate / m1.slo
                            p2 = m2.req_rate / m2.slo
                            others = max((kvpr(press[g], free[g])
                                          for g in range(gpu_num) if g != src and g != dst),
                                         default=0.0)
                            cand = max(kvpr(press[src] - p1 + p2, free[src] - d),
                                       kvpr(press[dst] - p2 + p1, free[dst] + d),
                                       others)
                            if cand < cur and (best is None or cand < best[0]):
                                best = (cand, 'swap', src, dst, (m1, m2))
            if best:
                _, kind, src, dst, payload = best
                if kind == 'move':
                    placement[src].remove(payload)
                    placement[dst].append(payload)
                    press[src] -= payload.req_rate / payload.slo
                    free[src] += payload.model_size
                    press[dst] += payload.req_rate / payload.slo
                    free[dst] -= payload.model_size
                else:
                    m1, m2 = payload
                    placement[src].remove(m1); placement[src].append(m2)
                    placement[dst].remove(m2); placement[dst].append(m1)
                    press[src] += m2.req_rate / m2.slo - m1.req_rate / m1.slo
                    free[src] += m2.model_size - m1.model_size
                    press[dst] += m1.req_rate / m1.slo - m2.req_rate / m2.slo
                    free[dst] += m1.model_size - m2.model_size
                improved = True
        return placement, press, free

    def score(press, free):
        best = 0.0
        for g in range(gpu_num):
            if free[g] > 0:
                best = max(best, press[g] / free[g])
            elif press[g] > 0:
