        placement, press, free = res
        placement, press, free = refine(placement, press, free)
        s = score(press, free)
        if s < best_score:
            best_score, best_place = s, placement

    if best_place is None:
        raise ValueError("Cannot fit all models into GPUs")

    return best_place

